CREATE TABLE `addresses` (
  `id` int NOT NULL AUTO_INCREMENT,
  `userId` int NOT NULL,
  `fullName` varchar(255) COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `phone` varchar(255) COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `provinceCode` varchar(255) COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `provinceName` varchar(255) COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `districtCode` varchar(255) COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `districtName` varchar(255) COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `wardCode` varchar(255) COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `wardName` varchar(255) COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `street` varchar(255) COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `isDefault` tinyint(1) DEFAULT '0',
  `createdAt` datetime NOT NULL,
  `updatedAt` datetime NOT NULL,
  PRIMARY KEY (`id`) /*T![clustered_index] CLUSTERED */,
  KEY `userId` (`userId`),
  CONSTRAINT `addresses_ibfk_1` FOREIGN KEY (`userId`) REFERENCES `users` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci AUTO_INCREMENT=120004;
