CREATE TABLE `appointments` (
  `id` int NOT NULL AUTO_INCREMENT,
  `userId` int NOT NULL,
  `staffId` int DEFAULT NULL,
  `branchId` int NOT NULL,
  `serviceId` int NOT NULL,
  `date` date NOT NULL,
  `startTime` varchar(255) COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `endTime` varchar(255) COLLATE utf8mb4_0900_ai_ci DEFAULT NULL,
  `status` enum('awaiting_deposit','pending','confirmed','in_progress','completed','cancelled') COLLATE utf8mb4_0900_ai_ci DEFAULT 'awaiting_deposit',
  `note` text COLLATE utf8mb4_0900_ai_ci DEFAULT NULL,
  `totalPrice` decimal(10,2) DEFAULT NULL,
  `createdAt` datetime NOT NULL,
  `updatedAt` datetime NOT NULL,
  `cancelReason` text COLLATE utf8mb4_0900_ai_ci DEFAULT NULL,
  `commissionAmount` decimal(10,2) DEFAULT '0.00',
  `orderId` int DEFAULT NULL,
  `depositAmount` decimal(10,2) DEFAULT NULL,
  `depositStatus` enum('pending','paid','refunded') COLLATE utf8mb4_0900_ai_ci DEFAULT 'pending',
  `paymentDeadline` datetime DEFAULT NULL,
  `isWalkIn` tinyint(1) DEFAULT '0',
  PRIMARY KEY (`id`) /*T![clustered_index] CLUSTERED */,
  KEY `userId` (`userId`),
  KEY `staffId` (`staffId`),
  KEY `branchId` (`branchId`),
  KEY `serviceId` (`serviceId`),
  KEY `orderId` (`orderId`),
  CONSTRAINT `appointments_ibfk_247` FOREIGN KEY (`userId`) REFERENCES `users` (`id`) ON UPDATE CASCADE,
  CONSTRAINT `appointments_ibfk_248` FOREIGN KEY (`staffId`) REFERENCES `users` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `appointments_ibfk_249` FOREIGN KEY (`branchId`) REFERENCES `branches` (`id`) ON UPDATE CASCADE,
  CONSTRAINT `appointments_ibfk_250` FOREIGN KEY (`serviceId`) REFERENCES `services` (`id`) ON UPDATE CASCADE,
  CONSTRAINT `appointments_ibfk_251` FOREIGN KEY (`orderId`) REFERENCES `orders` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci AUTO_INCREMENT=510006;
