CREATE TABLE `cash_flow_transactions` (
  `id` int NOT NULL AUTO_INCREMENT,
  `branchId` int DEFAULT NULL,
  `type` enum('receipt','payment') COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `amount` decimal(10,2) NOT NULL,
  `category` enum('utilities','rent','salary','supplier_payment','outside_income','refund','deposit','other') COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `method` enum('cash','bank') COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `status` enum('pending','completed','cancelled') COLLATE utf8mb4_0900_ai_ci DEFAULT 'completed',
  `referenceType` enum('order','appointment','inventory_import','manual') COLLATE utf8mb4_0900_ai_ci DEFAULT 'manual',
  `referenceId` int DEFAULT NULL,
  `note` text COLLATE utf8mb4_0900_ai_ci DEFAULT NULL,
  `createdBy` int DEFAULT NULL,
  `createdAt` datetime NOT NULL,
  `updatedAt` datetime NOT NULL,
  PRIMARY KEY (`id`) /*T![clustered_index] CLUSTERED */,
  KEY `createdBy` (`createdBy`),
  KEY `branchId` (`branchId`),
  CONSTRAINT `cash_flow_transactions_ibfk_1` FOREIGN KEY (`createdBy`) REFERENCES `users` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `cash_flow_transactions_ibfk_2` FOREIGN KEY (`branchId`) REFERENCES `branches` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci AUTO_INCREMENT=660008;
