CREATE TABLE `orders` (
  `id` int NOT NULL AUTO_INCREMENT,
  `userId` int NOT NULL,
  `totalAmount` decimal(10,2) NOT NULL,
  `status` enum('pending','confirmed','packing','shipping','delivered','completed','cancelled') COLLATE utf8mb4_0900_ai_ci DEFAULT 'pending',
  `trackingCode` varchar(255) COLLATE utf8mb4_0900_ai_ci DEFAULT NULL,
  `paymentMethod` enum('cod','vnpay','cash','sepay') COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `paymentStatus` enum('pending','paid','refunded') COLLATE utf8mb4_0900_ai_ci DEFAULT 'pending',
  `address` varchar(255) COLLATE utf8mb4_0900_ai_ci DEFAULT NULL,
  `phone` varchar(255) COLLATE utf8mb4_0900_ai_ci DEFAULT NULL,
  `voucherId` int DEFAULT NULL,
  `discountAmount` decimal(10,2) DEFAULT '0.00',
  `createdAt` datetime NOT NULL,
  `updatedAt` datetime NOT NULL,
  `appointmentId` int DEFAULT NULL,
  PRIMARY KEY (`id`) /*T![clustered_index] CLUSTERED */,
  KEY `userId` (`userId`),
  KEY `voucherId` (`voucherId`),
  CONSTRAINT `orders_ibfk_115` FOREIGN KEY (`userId`) REFERENCES `users` (`id`) ON UPDATE CASCADE,
  CONSTRAINT `orders_ibfk_116` FOREIGN KEY (`voucherId`) REFERENCES `vouchers` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci AUTO_INCREMENT=510012;
