CREATE TABLE `users` (
  `id` int NOT NULL AUTO_INCREMENT,
  `fullName` varchar(255) COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `email` varchar(255) COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `googleId` varchar(255) COLLATE utf8mb4_0900_ai_ci DEFAULT NULL,
  `password` varchar(255) COLLATE utf8mb4_0900_ai_ci DEFAULT NULL,
  `phone` varchar(255) COLLATE utf8mb4_0900_ai_ci DEFAULT NULL,
  `avatar` varchar(255) COLLATE utf8mb4_0900_ai_ci DEFAULT NULL,
  `role` enum('customer','staff','admin','warehouse_staff','service_staff','accountant','accountant_staff','receptionist') COLLATE utf8mb4_0900_ai_ci DEFAULT 'customer',
  `branchId` int DEFAULT NULL,
  `createdAt` datetime NOT NULL,
  `updatedAt` datetime NOT NULL,
  `loyaltyPoints` int DEFAULT '0',
  `rank` enum('Silver','Gold','Diamond') COLLATE utf8mb4_0900_ai_ci DEFAULT 'Silver',
  `workStatus` enum('available','break','busy') COLLATE utf8mb4_0900_ai_ci DEFAULT 'available',
  `isActive` tinyint(1) DEFAULT '1',
  `isEmailVerified` tinyint(1) DEFAULT '0',
  PRIMARY KEY (`id`) /*T![clustered_index] CLUSTERED */,
  UNIQUE KEY `email` (`email`),
  KEY `branchId` (`branchId`),
  UNIQUE KEY `idx_googleId` (`googleId`),
  CONSTRAINT `users_ibfk_1` FOREIGN KEY (`branchId`) REFERENCES `branches` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci AUTO_INCREMENT=660010;
